IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'必测项' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*外观' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'外观') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'必测项', 10, N'{"v":2,"group":"必测项","name":"*外观","req":"清洁、无破损无压痕，无裂纹,无倾斜等缺陷；切面平整无锯齿纹路，无明显缺角；切面无残留炭渣","method":"常规抽检","quality":"外观","instrument":"目视","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"生产量*1%","content":"检验炭棒外观是否符合要求"}', N'seed', SYSDATETIME());
