IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'必测项' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*出货重量' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'炭棒重量') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'必测项', 30, N'{"v":2,"group":"必测项","name":"*出货重量","req":">22g","method":"常规抽检","quality":"炭棒重量","instrument":"电子秤","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"生产量*1%","content":"检验炭棒出货重量是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'必测项' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*抗压强度（裸棒）' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'强度') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'必测项', 40, N'{"v":2,"group":"必测项","name":"*抗压强度（裸棒）","req":"将炭棒水平放置在水平面板上，设置下压速度5mm/min，按测试键，仪器自动下压，断裂后读取压断时最大力压力值。\n控制标准：>50kgf","method":"常规抽检","quality":"强度","instrument":"普研PY-880","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验炭棒抗压强度是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'必测项' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*压降测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'压降') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'必测项', 50, N'{"v":2,"group":"必测项","name":"*压降测试","req":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，测试流速0.24L/min，滤前前后接装压力表，压力表距离滤芯接口位置长度50mm，通水10min后记录压差值（滤芯前压-后压）。\n控制标准：≤25kpa","method":"常规抽检","quality":"压降","instrument":"数显压力表","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验炭棒压降是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'必测项' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*黑水及颗粒物测试（无黑后）' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'黑水测试') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'必测项', 60, N'{"v":2,"group":"必测项","name":"*黑水及颗粒物测试（无黑后）","req":"将炭棒组装好装入滤瓶（透明大T），按进水方向通水，测试流速0.24±0.05L/min\n1.用烧杯接第一杯水250ml，观察出水及测试浊度值；\n2.冲水5min后，浸泡24H，陶瓷杯接出水100ml，观察出水情况及测试浊度值；\n控制标准：1.初始：轻微黑水，浊度≤20NTU\n2.浸泡24H：无肉眼可见黑水，浊度≤3NTU","method":"常规抽检","quality":"黑水测试","instrument":"烧杯，哈希2100q","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验炭棒黑水测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'必测项' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*黑水及颗粒物测试（无黑后）' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'浸泡颗粒物') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'必测项', 70, N'{"v":2,"group":"必测项","name":"*黑水及颗粒物测试（无黑后）","req":"将炭棒组装好装入滤瓶（可旋盖大T），按进水方向通水，测试流速0.24±0.05L/min，\n完成黑水测试后，炭棒静置浸泡24H，用陶瓷杯接出水100ml，正常照明下，用肉眼观察杯底部颗粒物，颗粒物≤4颗\n控制标准：浸泡4H颗粒物≤4颗","method":"常规抽检","quality":"浸泡颗粒物","instrument":"烧杯","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验炭棒浸泡颗粒物是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*碱性性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'*初始PH增加值测试') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 80, N'{"v":2,"group":"型式检验","name":"*碱性性能测试","req":"将炭棒组装好装入伊可普工装，按进水方向通RO纯水（水效水500+RO机），测试流速0.24L/min,冲水5min后，浸泡30min后，测试出水PH，接水量为500ml。\n控制标准：初始PH增加值＞3.0","method":"常规抽检","quality":"*初始PH增加值测试","instrument":"PH计","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验炭棒初始PH增加值测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*碱性性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'*浸泡24H口感测试') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 90, N'{"v":2,"group":"型式检验","name":"*碱性性能测试","req":"将炭棒组装好装入伊可普工装，按进水方向通RO纯水（水效水500+RO机），测试流速0.24L/min,冲水5min后，浸泡24H后，接出水（连续接五杯，接水量为100ml）及原水，测试口感、PH、TDS\n控制标准：1.五杯口感均无异常\n2.第一杯TDS增加值小于150\n3.第一杯出水PH增加值＞4.0","method":"常规抽检","quality":"*浸泡24H口感测试","instrument":"PH计、TDS笔","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验浸泡24H口感测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*碱性性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'碱性寿命') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 100, N'{"v":2,"group":"型式检验","name":"*碱性性能测试","req":"将炭棒组装好装入伊可普工装，全程RO纯水（水效水500+RO机）加标测试控制水温25±3℃、流速0.24L/min，在额定净水0%、25%、50%、75%、100%，浸泡30min后取炭棒滤后水进行测试记录节点流速及炭棒出水PH（寿命1000L，每天冲水约145L，测试周期约为7天）。寿命1000L，PH增加值≥0.5","method":"型式检测报告","quality":"碱性寿命","instrument":"PH计","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"型式检验半年一次","sampling":"","content":"检验炭棒碱性寿命测试是否符合要求"}', N'seed', SYSDATETIME());
